import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-emje7bwI.js";var l=JSON.parse(`{"path":"/documentation/best-practices.html","title":"Best Practices","lang":"en-US","frontmatter":{"title":"Best Practices"},"git":{"updatedTime":1790451733000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Opus 5.5","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"4a29e014ef1e61227140e96264c49cf64cd3183d","time":1790451733000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"A captured log reaches its column whole on Oracle and SQL Server","coAuthors":[{"name":"Claude Opus 5.5","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/best-practices.md"}`),u={name:`best-practices.md`};function d(s,l,u,d,f,p){let m=a(`RouteLink`);return n(),o(`div`,null,[l[41]||=t(`<h1 id="best-practices" tabindex="-1"><a class="header-anchor" href="#best-practices"><span>Best Practices</span></a></h1><p>These practices apply to <strong>Quartz 3.x and 4.x</strong>; where the two differ, the text says so. The C# samples are 4.x, and the text gives the 3.x spelling where it differs.</p><h2 id="designing-a-job" tabindex="-1"><a class="header-anchor" href="#designing-a-job"><span>Designing a job</span></a></h2><h3 id="assume-the-job-will-run-more-than-once" tabindex="-1"><a class="header-anchor" href="#assume-the-job-will-run-more-than-once"><span>Assume the job will run more than once</span></a></h3><p>By default a firing runs <strong>at most once</strong>. If a node dies mid-execution, its fired-trigger row is cleaned up and that occurrence is lost; the trigger continues from its next scheduled time. <a href="#what-requestsrecovery-re-runs-and-when">Requesting recovery</a> changes this to <strong>at least once</strong>.</p><p>Work can also run twice in these cases:</p><ul><li><strong>A node wrongly declared dead.</strong> Its peers release its acquired triggers and re-schedule its recovery-requesting executions while it is still running them. See <a href="#clocks-in-a-cluster">Clocks in a cluster</a>.</li><li><strong>Misfire catch-up.</strong> A trigger set to ignore misfires fires every missed occurrence, as fast as the pool allows. See <a href="#choosing-a-misfire-instruction-by-its-consequence">Choosing a misfire instruction</a>.</li><li><strong>A refire.</strong> <code>JobExecutionException.RefireImmediately</code> re-runs the same firing on the same worker.</li><li><strong>Two schedulers that are not one cluster.</strong> The most common cause in practice. See <a href="#one-name-per-cluster-one-id-per-node">One name per cluster, one id per node</a>.</li></ul><p>Sidekiq, Hangfire and Kubernetes <code>CronJob</code> make no exactly-once promise either, and all three ask for idempotent jobs. Design jobs so that a second run does no harm:</p><ul><li>A job that computes an absolute state and upserts it (a rollup, a cache refresh, a regenerated report) needs nothing more.</li><li>A job with an external side effect needs an idempotency key.</li></ul><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Key the occurrence, not the firing: a recovered execution has a new trigger and a new</span></span>
<span class="line">    <span class="token comment">// fire instance id.</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">string</span></span> period <span class="token operator">=</span> context<span class="token punctuation">.</span>MergedJobDataMap<span class="token punctuation">.</span><span class="token function">GetString</span><span class="token punctuation">(</span><span class="token string">&quot;period&quot;</span><span class="token punctuation">)</span><span class="token operator">!</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">string</span></span> idempotencyKey <span class="token operator">=</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key</span><span class="token punctuation">}</span></span><span class="token string">:</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">period</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Record the key and do the work in one transaction, with a unique index on the key.</span></span>
<span class="line">    <span class="token keyword">await</span> ledger<span class="token punctuation">.</span><span class="token function">ChargeOnce</span><span class="token punctuation">(</span>idempotencyKey<span class="token punctuation">,</span> period<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Rules for the key:</p><ul><li><strong>Derive it from the occurrence, not from <code>FireInstanceId</code> or the trigger.</strong> A recovered execution runs on a new trigger in the <code>RECOVERING_JOBS</code> group with a new fire instance id, so a key built from either would not match the run it repeats. Use <code>FireInstanceId</code> to interrupt one execution (<code>IScheduler.InterruptFireInstance</code>), not to deduplicate.</li><li><strong>Write the key and the effect in one transaction, with a unique index on the key.</strong> A read followed by a write leaves a race between two executions.</li><li><strong>Keep the keys for as long as work can be replayed.</strong> A recovery run can arrive minutes after the original; a manual re-trigger can arrive months after.</li></ul><p>On Quartz 3.x the signature is <code>Task Execute(IJobExecutionContext context)</code>; the rest is the same.</p><h3 id="what-requestsrecovery-re-runs-and-when" tabindex="-1"><a class="header-anchor" href="#what-requestsrecovery-re-runs-and-when"><span>What RequestsRecovery re-runs, and when</span></a></h3><p><code>RequestRecovery</code> is off by default. It needs a persistent store: <code>RAMJobStore</code> loses its state with the process.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ChargeInvoicesJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;charge-invoices&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">RequestRecovery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Recovery runs when a scheduler with a persistent store starts, and when a clustered scheduler&#39;s cluster manager decides a peer has stopped checking in. For each fired-trigger row the failed instance left behind:</p><ul><li>If the job <strong>requests recovery</strong>, the row becomes a new trigger in the <code>RECOVERING_JOBS</code> group. It fires as soon as the scheduler can run it and carries the original trigger&#39;s job data.</li><li>Otherwise the row is deleted and that occurrence is lost.</li></ul><p>Recovery re-runs only executions that were interrupted by a process dying or a machine going away. It is not a retry: a job that threw has completed its firing.</p><p>A trigger that was acquired but never fired is not recovered. The fired-trigger row is inserted at acquisition with no job name and <code>REQUESTS_RECOVERY</code> false, and is updated to <code>EXECUTING</code> with the job&#39;s real flags only when the trigger fires. Cluster recovery also releases such a reservation back to <code>WAITING</code>, so its own trigger fires it again in the ordinary way.</p><p>A recovered execution can tell that it is one:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>context<span class="token punctuation">.</span>Recovering<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">TriggerKey</span> original <span class="token operator">=</span> context<span class="token punctuation">.</span>RecoveringTriggerKey<span class="token operator">!</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">string</span></span> firstFiredAt <span class="token operator">=</span> context<span class="token punctuation">.</span>MergedJobDataMap<span class="token punctuation">.</span><span class="token function">GetString</span><span class="token punctuation">(</span></span>
<span class="line">        SchedulerConstants<span class="token punctuation">.</span>FailedJobOriginalTriggerFireTime<span class="token punctuation">)</span><span class="token operator">!</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">LogWarning</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token string">&quot;Recovering work that {Trigger} started at {FirstFiredAt} on a node that did not finish it.&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        original<span class="token punctuation">,</span> firstFiredAt<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>SchedulerConstants.FailedJobOriginalTriggerName</code> and <code>…OriginalTriggerGroup</code> are in the same map.</p><p>On both versions, recovery of a <code>[DisallowConcurrentExecution]</code> job is deferred on first detection, for roughly two check-in intervals plus the check-in misfire threshold, because a node that missed one check-in may still be running the job.</p><p>Turning recovery on means preferring a job that ran twice to work that never ran. Reports and reconciliations usually want it. A job that refreshes something every five minutes usually does not, because the next firing is soon.</p><h3 id="what-happens-when-a-job-throws" tabindex="-1"><a class="header-anchor" href="#what-happens-when-a-job-throws"><span>What happens when a job throws</span></a></h3><p>An exception that escapes <code>Execute</code> is caught, logged, wrapped in a <code>JobExecutionException</code> and handed to the trigger, which completes the firing normally. <strong>The job is not re-executed and the schedule is unchanged</strong>, on both versions, whatever Java Quartz&#39;s best-practices page says.</p><p><code>RefireImmediately</code> re-runs the same firing on the same worker, at once, and increments <code>IJobExecutionContext.RefireCount</code>. It has no backoff, so an unbounded refire is a tight failure loop. Bound it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">try</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">await</span> gateway<span class="token punctuation">.</span><span class="token function">Publish</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">HttpRequestException</span> ex<span class="token punctuation">)</span> <span class="token keyword">when</span> <span class="token punctuation">(</span>context<span class="token punctuation">.</span>RefireCount <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// A refire runs this firing again immediately, on the same worker, with no delay of its own.</span></span>
<span class="line">    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobExecutionException</span><span class="token punctuation">(</span>ex<span class="token punctuation">)</span> <span class="token punctuation">{</span> RefireImmediately <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On Quartz 3.x the flag is a constructor argument: <code>throw new JobExecutionException(ex, refireImmediately: true)</code>.</p><p>The same exception has two more flags:</p><ul><li><code>UnscheduleFiringTrigger</code> removes the trigger that fired.</li><li><code>UnscheduleAllTriggers</code> removes every trigger for the job.</li></ul><p><code>RefireImmediately</code> wins over both.</p><p>A job that ends because its cancellation token fired is <strong>not</strong> a failure: the scheduler logs it at information level and completes the firing.</p><h3 id="give-the-trigger-a-retry-policy" tabindex="-1"><a class="header-anchor" href="#give-the-trigger-a-retry-policy"><span>Give the trigger a retry policy</span></a></h3><p><strong>Quartz 4.x puts a retry policy on the trigger; 3.x has none.</strong></p><p>On 4.x a trigger carries a <code>RetryPolicy</code>, made only by <code>Fixed</code>, <code>Exponential</code> or <code>Explicit</code>. A job that throws is re-fired at the stated waits, with nothing else to opt into:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>PublishReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;report&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>PublishReportJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span><span class="token string">&quot;report&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 0 2 * * ?&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token comment">// 30s, 1m, 2m, 4m, 8m — never longer than ten minutes, and never past the trigger&#39;s</span></span>
<span class="line">        <span class="token comment">// own next occurrence.</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithRetryPolicy</span><span class="token punctuation">(</span>RetryPolicy<span class="token punctuation">.</span><span class="token function">Exponential</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token named-parameter punctuation">maxAttempts</span><span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token named-parameter punctuation">initialDelay</span><span class="token punctuation">:</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromSeconds</span><span class="token punctuation">(</span><span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token named-parameter punctuation">factor</span><span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token named-parameter punctuation">maxDelay</span><span class="token punctuation">:</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromMinutes</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A retry is a new firing of the same occurrence at a later time:</p><ul><li>It is written to the job store, survives a restart, and every node in the cluster sees it.</li><li><code>IJobExecutionContext.RetryAttempt</code> counts it.</li><li><code>ScheduledFireTimeUtc</code> still reports the scheduled occurrence, not the time the retry ran.</li></ul><p>A retry is not <code>RefireImmediately</code> with a delay. A refire runs in process, persists nothing and keeps the execution slot, and the two counters move independently.</p><p>Three rules decide whether a policy does anything:</p><ul><li>A retry that would land at, or within a second of, the trigger&#39;s next occurrence is dropped. A policy whose waits are longer than the gap between occurrences does nothing.</li><li>Running out of attempts is not an error. The trigger returns to its schedule, not to <code>TriggerState.Error</code>.</li><li>A retry uses up nothing: no <code>SimpleTrigger</code> repeat count, no recurrence <code>COUNT</code>, no <code>TimesTriggered</code>.</li></ul><p>See <a href="/documentation/quartz-4.x/how-tos/retrying-failed-jobs">Retrying Failed Jobs</a>.</p><p><strong>On 3.x there is only immediate refire and the next scheduled occurrence.</strong> To retry later, do not <code>Task.Delay</code> inside the job, which holds a worker for the whole wait. Either store a one-off trigger a few minutes ahead and return, or let the next occurrence pick the work up, if the work is defined by its inputs. <a href="/documentation/quartz-4.x/how-tos/rescheduling-jobs#retrying-inside-the-job">Rescheduling Jobs</a> shows both (<a href="/documentation/quartz-3.x/how-tos/rescheduling-jobs">3.x</a>).</p><h3 id="keep-job-data-small-string-safe-and-free-of-secrets" tabindex="-1"><a class="header-anchor" href="#keep-job-data-small-string-safe-and-free-of-secrets"><span>Keep job data small, string-safe and free of secrets</span></a></h3><p>Put an identifier in the job data and load what it names when the job runs. Job data lives as long as the trigger, so a stored object goes stale; large values bloat the store; and serialized types break as code changes. Java Quartz, Hangfire and Sidekiq give the same rule.</p><ul><li><strong>No credentials, tokens or connection strings.</strong> Job data appears in every backup, in the dashboard and in the HTTP API. Get secrets from the container.</li><li><strong>String-only storage removes the versioning problem.</strong> With it on (<code>StoreJobDataAsStrings</code> in 4.x, the flat key <code>quartz.jobStore.useProperties</code> on both), every value must be a string. Turn it on at the start of a project, not in the middle.</li><li><strong>Read <code>IJobExecutionContext.MergedJobDataMap</code></strong>: the job&#39;s map with the trigger&#39;s laid over it. This lets several triggers drive one job with different inputs. In 4.x the scheduler context is not part of the merge; read scheduler-wide values from <code>context.Scheduler.Context</code>.</li><li><strong>Spell a job&#39;s key once.</strong> Give the job class a <code>public static readonly JobKey</code> and use it everywhere. The <a href="/documentation/quartz-4.x/how-tos/job-template">job template how-to</a> does this (<a href="/documentation/quartz-3.x/how-tos/job-template">3.x</a>).</li></ul><p>See <a href="/documentation/quartz-4.x/tutorial/job-data-map">Job Data Map (4.x)</a> and <a href="/documentation/quartz-3.x/tutorial/more-about-jobs">More About Jobs (3.x)</a>.</p><h2 id="deciding-what-may-run-at-the-same-time" tabindex="-1"><a class="header-anchor" href="#deciding-what-may-run-at-the-same-time"><span>Deciding what may run at the same time</span></a></h2><table><thead><tr><th>To limit</th><th>Use</th></tr></thead><tbody><tr><td>Overlapping executions of one job key</td><td><a href="#disallowconcurrentexecution-bounds-one-job-key"><code>[DisallowConcurrentExecution]</code></a></td></tr><tr><td>How many of a category of work run at once</td><td><a href="#execution-groups-bound-a-category-of-work">Execution groups</a></td></tr></tbody></table><p>Both apply at once; a trigger must satisfy both to be acquired. Neither is a queue: see <a href="#held-back-work-misfires-it-does-not-queue">Held-back work misfires</a>.</p><h3 id="disallowconcurrentexecution-bounds-one-job-key" tabindex="-1"><a class="header-anchor" href="#disallowconcurrentexecution-bounds-one-job-key"><span>DisallowConcurrentExecution bounds one job key</span></a></h3><p>The attribute stops two executions of <strong>the same job detail</strong> overlapping. It is not per class: two jobs of the same class with different keys run concurrently; one job with three triggers does not.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token punctuation">[</span><span class="token attribute"><span class="token class-name">DisallowConcurrentExecution</span></span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">RebuildSearchIndexJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// One execution of this job key at a time — across the whole cluster, with a persistent store.</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>With a persistent store this holds <strong>across the cluster</strong>. Trigger acquisition skips a job that already has a live row in <code>QRTZ_FIRED_TRIGGERS</code>, and the fire path checks again under the cluster-wide <code>TRIGGER_ACCESS</code> lock before committing the firing. The job&#39;s other triggers are <code>BLOCKED</code> meanwhile. The check and the firing commit together under one database lock, not a client-side lease.</p><p>The guarantee is only as good as the fired-triggers table. A node wrongly declared dead has its rows deleted while its job is still running. Recovery defers that case on first detection, but a window remains; see <a href="#clocks-in-a-cluster">Clocks in a cluster</a>. Use the attribute to keep the normal case orderly, and idempotence to keep the abnormal case correct.</p><p>A job with <code>[PersistJobDataAfterExecution]</code> should also carry <code>[DisallowConcurrentExecution]</code>. Otherwise two concurrent executions race over which job data is stored.</p><h3 id="execution-groups-bound-a-category-of-work" tabindex="-1"><a class="header-anchor" href="#execution-groups-bound-a-category-of-work"><span>Execution groups bound a category of work</span></a></h3><p>An execution group is a tag on a trigger. An execution limit caps how many triggers of that group run at once. Use it for rules like &quot;reindexing may use at most two workers&quot;: the attribute cannot express that because reindexing is many job keys, and a smaller thread pool would throttle everything else too.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>ReindexTenantJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;reindex-acme&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithExecutionGroup</span><span class="token punctuation">(</span><span class="token string">&quot;reindex&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 0 3 * * ?&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;reindex&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    limits<span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">8</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A limit is <strong>per node</strong> by default: three nodes each configured with <code>2</code> can run six. That fits hardware capacity, not a quota. For a quota, Quartz 4.x adds <code>ExecutionLimitScope.Cluster</code>, counted from the fired-triggers table; 3.x has only the per-node form.</p><p>The cluster-scoped limit&#39;s guarantees and cost are on <a href="/documentation/quartz-4.x/tutorial/execution-groups">Execution Groups (4.x)</a> and <a href="/documentation/quartz-3.x/tutorial/execution-groups">Execution Groups (3.x)</a>.</p><h3 id="held-back-work-misfires-it-does-not-queue" tabindex="-1"><a class="header-anchor" href="#held-back-work-misfires-it-does-not-queue"><span>Held-back work misfires; it does not queue</span></a></h3><p>A trigger that acquisition skips, because its job is running or its group is at its limit, keeps its original next fire time. If it is held back past the misfire threshold, it misfires, and the <strong>trigger&#39;s misfire instruction</strong> decides whether that occurrence is skipped, run late, or run alongside the ones behind it.</p><p>For a <code>[DisallowConcurrentExecution]</code> job this happens at once: when the running execution completes, the store applies each unblocked trigger&#39;s misfire policy in the same transaction that unblocks it.</p><p>So choose the concurrency limit and the misfire instruction together:</p><ul><li>Occurrences must not be dropped: use an instruction that catches up.</li><li>Occurrences only matter when fresh: use an instruction that skips.</li></ul><h2 id="choosing-a-misfire-instruction-by-its-consequence" tabindex="-1"><a class="header-anchor" href="#choosing-a-misfire-instruction-by-its-consequence"><span>Choosing a misfire instruction by its consequence</span></a></h2>`,69),e(`p`,null,[l[1]||=r(`A misfire is a firing that did not run within the misfire threshold of its scheduled time. Causes: the scheduler was down, the thread pool was full, or the trigger was held back. The mechanics are in `,-1),c(m,{to:`/documentation/troubleshooting.html#misfire-handling`},{default:i(()=>[...l[0]||=[r(`Troubleshooting`,-1)]]),_:1}),l[2]||=r(`.`,-1)]),l[42]||=t(`<table><thead><tr><th>Consequence</th><th>Cron, recurrence, calendar-interval, daily-time-interval</th><th>Simple</th></tr></thead><tbody><tr><td>Run every missed occurrence</td><td><code>IgnoreMisfires</code></td><td><code>IgnoreMisfires</code></td></tr><tr><td>Run one now, then resume the schedule</td><td><code>FireAndProceed</code></td><td><code>FireNow</code> or a <code>Now…</code> variant</td></tr><tr><td>Skip what was missed; resume at the next scheduled time</td><td><code>DoNothing</code></td><td><code>NextWithExistingCount</code> or <code>NextWithRemainingCount</code></td></tr></tbody></table><p><code>IgnoreMisfires</code> catches up as fast as the thread pool allows: a trigger firing every fifteen seconds that was down for five minutes fires twenty times in a row.</p><p>The default on every trigger is <code>SmartPolicy</code>. It resolves to:</p><table><thead><tr><th>Trigger</th><th><code>SmartPolicy</code> does</th></tr></thead><tbody><tr><td>Cron, recurrence, calendar-interval, daily-time-interval</td><td>Fire once now, then resume</td></tr><tr><td>Simple, one-shot</td><td>Fire now</td></tr><tr><td>Simple, repeats forever</td><td>Skip to the next occurrence, keeping the remaining count</td></tr><tr><td>Simple, finite repeat count</td><td>Fire now, keeping the count it has</td></tr></tbody></table><p>To choose, ask whether an occurrence is about a moment or about a backlog:</p><ul><li>A nightly settlement that missed 02:00 should still run, late and once: the default is right.</li><li>An hourly report that missed six hours: <code>DoNothing</code> if the report describes &quot;now&quot;; <code>IgnoreMisfires</code> if each report describes its own hour.</li><li>A cache refresh that missed anything should just do the next one.</li></ul><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>NightlyRollupJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-rollup&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 0 2 * * ?&quot;</span><span class="token punctuation">,</span> x <span class="token operator">=&gt;</span> x</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">InTimeZone</span><span class="token punctuation">(</span>TimeZones<span class="token punctuation">.</span><span class="token function">FindById</span><span class="token punctuation">(</span><span class="token string">&quot;Europe/Helsinki&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithMisfireInstruction</span><span class="token punctuation">(</span>CronTriggerMisfireInstruction<span class="token punctuation">.</span>DoNothing<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>On Quartz 3.x that is <code>.WithMisfireHandlingInstructionDoNothing()</code>. 4.x replaced the named methods with <code>WithMisfireInstruction</code>, taking a per-family enum.</p><p>Two traps:</p><ul><li><strong><code>IgnoreMisfires</code> catches up; it does not skip.</strong> It ignores the misfire <em>policy</em>: the trigger is excluded from misfire handling, stays acquirable however late it is, and fires every missed occurrence in turn.</li><li><strong>The threshold differs by store.</strong> A persistent store treats a firing as misfired at sixty seconds late; <code>RAMJobStore</code> at five seconds. These are the defaults on both versions. Misfire behaviour tested only against the in-memory store has not met the production threshold.</li></ul><h3 id="do-not-start-a-trigger-in-the-past" tabindex="-1"><a class="header-anchor" href="#do-not-start-a-trigger-in-the-past"><span>Do not start a trigger in the past</span></a></h3><p>A trigger whose start time is already past the misfire threshold when it is stored has misfired before its first firing. Its misfire instruction decides what happens; by default it fires immediately. This is the most common cause of a schedule firing when nobody expected it.</p><p>Two habits cause it:</p><ul><li>Rebuilding a trigger from <code>GetTriggerBuilder()</code> keeps the <em>original</em> start time, which may be months old.</li><li>Re-registering triggers on every deployment with a start time of &quot;now plus a few seconds&quot; ties the schedule to each process start instead of the calendar.</li></ul><p>With a persistent store, give a repeating trigger a fixed start time and add it only if it is missing:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>HourlySyncJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;hourly-sync&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">StartAt</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">DateTimeOffset</span><span class="token punctuation">(</span><span class="token number">2026</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> TimeSpan<span class="token punctuation">.</span>Zero<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithSimpleSchedule</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span> s</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithInterval</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromHours</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">RepeatForever</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="daylight-saving-clock-changes-and-cluster-skew" tabindex="-1"><a class="header-anchor" href="#daylight-saving-clock-changes-and-cluster-skew"><span>Daylight saving, clock changes and cluster skew</span></a></h2><h3 id="say-the-schedule-in-the-trigger-type-that-means-it" tabindex="-1"><a class="header-anchor" href="#say-the-schedule-in-the-trigger-type-that-means-it"><span>Say the schedule in the trigger type that means it</span></a></h3><p>Most daylight saving surprises come from the choice of trigger type.</p><table><thead><tr><th>You mean</th><th>Trigger</th><th>Across a daylight saving transition</th></tr></thead><tbody><tr><td>Every N seconds, minutes or hours of real time</td><td><code>SimpleTrigger</code></td><td>Spacing unchanged; the wall-clock time moves (03:00 becomes 04:00)</td></tr><tr><td>At this time of day, in this zone</td><td><code>CronTrigger</code>, <code>RecurrenceTrigger</code></td><td><a href="#the-two-daylight-saving-rules">The two rules below</a></td></tr><tr><td>Every N calendar days, months or years</td><td><code>CalendarIntervalTrigger</code></td><td>Shifts by the transition delta, unless <code>PreserveHourOfDayAcrossDaylightSavings</code> is set (off by default)</td></tr><tr><td>Repeatedly inside a daily window</td><td><code>DailyTimeIntervalTrigger</code></td><td>Wall-clock window, so the day&#39;s run gets longer or shorter</td></tr></tbody></table><p>Quartz cron states more than most cron dialects: <code>0 0 0 ? * MON#2</code> is the second Monday of the month and <code>0 0 0 LW 3 ?</code> the last weekday of March. It cannot state:</p><ul><li>a position counted from the end of a month, other than the last (<code>#</code> counts forwards, up to 5);</li><li>a fortnight;</li><li>a cadence its fields cannot divide. <code>0 0 0 1/3 * ?</code> restarts on the 1st of each month, so 31 January is followed by 1 February.</li></ul><p><code>RecurrenceTrigger</code> and its RFC 5545 rule state all three, on <a href="/documentation/quartz-4.x/tutorial/recurrencetrigger">4.x</a> and <a href="/documentation/quartz-3.x/tutorial/recurrencetrigger">3.x</a>. If you need several cron triggers, or a workaround inside an expression, use one.</p><table><thead><tr><th>Schedule</th><th>RFC 5545 rule</th></tr></thead><tbody><tr><td>Second-to-last Friday of the month</td><td><code>FREQ=MONTHLY;BYDAY=-2FR</code></td></tr><tr><td>Every other Monday</td><td><code>FREQ=WEEKLY;INTERVAL=2;BYDAY=MO</code></td></tr><tr><td>Every three days, not reset each month</td><td><code>FREQ=DAILY;INTERVAL=3</code></td></tr></tbody></table><p><strong><code>0 0 0 ? * MON/2</code> means three different things.</strong> It is a textual day-of-week with a step:</p><table><thead><tr><th>Version</th><th>Meaning</th></tr></thead><tbody><tr><td>3.x</td><td>Every other Monday</td></tr><tr><td>4.0</td><td><code>FormatException</code></td></tr><tr><td>4.1 and later</td><td>Same as <code>0 0 0 ? * 2/2</code>: Monday, Wednesday and Friday. 156 fires a year instead of 26, with nothing logged</td></tr></tbody></table><p>Audit for it before upgrading from 3.x to any 4.x. See <a href="/documentation/quartz-4.x/cron-expressions#mon-2-is-a-step-through-the-week"><code>MON/2</code> is a step through the week</a>, and <a href="/documentation/quartz-4.x/cron-expressions#forms-the-parser-refuses">Forms the parser refuses</a> for the six shapes 4.x rejects that 3.x accepted and reinterpreted.</p><p>4.x dropped the fortnight because its phase depended on whatever last evaluated the expression: a misfire, a restart or a failover recomputed it from a different day. <code>FREQ=WEEKLY;INTERVAL=2;BYDAY=MO</code> anchors on the trigger&#39;s start time instead.</p><h3 id="the-two-daylight-saving-rules" tabindex="-1"><a class="header-anchor" href="#the-two-daylight-saving-rules"><span>The two daylight saving rules</span></a></h3><p>A cron expression is never skipped by a transition, and never fires twice for one scheduled occurrence. Where it fires depends on the expression and the version:</p><ul><li>A <strong>fixed-time</strong> expression has plain values or comma lists in the second, minute and hour fields: <code>0 30 2 * * ?</code>, <code>0 0,30 2 * * ?</code>.</li><li>An <strong>interval</strong> expression has a wildcard, step or range in one of them: <code>0 * * * * ?</code>, <code>0 0/30 * * * ?</code>.</li></ul><table><thead><tr><th>Case</th><th>4.x</th><th>3.x</th></tr></thead><tbody><tr><td>Fixed-time, the time does not exist (spring forward)</td><td>Fires once, at the <strong>end of the gap</strong>: a daily 02:30 over a 02:00–03:00 gap fires at 03:00</td><td>Fires once, shifted forward by the delta, at 03:30</td></tr><tr><td>Fixed-time, the time occurs twice (fall back)</td><td>Fires once, at the first occurrence</td><td>Same as 4.x</td></tr><tr><td>Interval, the repeated hour (fall back)</td><td>Fires through <strong>both</strong> passes</td><td>Fires the hour once; &quot;every minute&quot; loses an hour of real time each autumn</td></tr><tr><td>Interval, the gap (spring forward)</td><td><code>0 30 * * * ?</code> fires at 03:00, for the occurrence the gap swallowed, and at 03:30</td><td>Fires once, at the shifted 03:30</td></tr></tbody></table><ul><li>Where the delta is not a whole hour (Australia/Lord_Howe, where 02:00 becomes 02:30), a daily <code>0 15 2 * * ?</code> fires at 02:30 on 4.x and 02:45 on 3.x.</li><li>Only 4.x&#39;s gap fire time matches the expression: <code>IsSatisfiedBy</code> says yes on 4.x and no on 3.x.</li></ul>`,33),e(`p`,null,[l[4]||=e(`strong`,null,`Name the time zone.`,-1),l[5]||=r(` A cron trigger with no zone uses `,-1),l[6]||=e(`code`,null,`TimeZoneInfo.Local`,-1),l[7]||=r(`: the developer's machine in development, and often UTC in a container. Look zones up with `,-1),l[8]||=e(`code`,null,`TimeZones.FindById`,-1),l[9]||=r(` (on 3.x, `,-1),l[10]||=e(`code`,null,`TimeZoneUtil`,-1),l[11]||=r(`) rather than `,-1),l[12]||=e(`code`,null,`TimeZoneInfo.FindSystemTimeZoneById`,-1),l[13]||=r(`; it resolves Windows and IANA identifiers on either platform. See the `,-1),c(m,{to:`/documentation/faq.html#daylight-saving-time-and-triggers`},{default:i(()=>[...l[3]||=[r(`FAQ's daylight saving section`,-1)]]),_:1}),l[14]||=r(`, and 4.x's `,-1),l[15]||=e(`a`,{href:`/documentation/quartz-4.x/tutorial/time-and-timeprovider`},`Time and TimeProvider`,-1),l[16]||=r(` on the clock and the zone as separate settings.`,-1)]),l[43]||=t(`<p><strong>Quartz cron puts seconds first.</strong> This causes more &quot;my job ran fifty times&quot; reports than daylight saving does. <code>* 0/5 * * * ?</code> is every second of every fifth minute; every five minutes is <code>0 0/5 * * * ?</code>. A five-field crontab line is not a Quartz expression: prepending <code>0</code> fixes the layout but not the day-of-week numbering, which is 0-6 from Sunday in crontab and 1-7 from Sunday here.</p><ul><li><strong>4.x:</strong> <code>CronExpression.Parse(line, CronFormat.Unix)</code> and <code>CronScheduleBuilder.Create(line, CronFormat.Unix)</code> read the five-field form as written, renumbering included, and store the canonical Quartz spelling.</li><li><strong>3.x:</strong> translate by hand, and check the day-of-week digit.</li></ul><p>See <a href="/documentation/quartz-4.x/tutorial/crontriggers">Cron Triggers (4.x)</a> and <a href="/documentation/quartz-3.x/tutorial/crontriggers">Cron Triggers (3.x)</a>.</p><h3 id="when-the-clock-moves-for-other-reasons" tabindex="-1"><a class="header-anchor" href="#when-the-clock-moves-for-other-reasons"><span>When the clock moves for other reasons</span></a></h3>`,4),e(`p`,null,[l[18]||=r(`Quartz schedules against the wall clock, which NTP corrections, manual changes and suspended virtual machines all move. A computed fire time is a point on the calendar, so after a backwards move it waits for the clock to catch up. Quartz resumes on its own after any change, within one `,-1),l[19]||=e(`code`,null,`IdleWaitTime`,-1),l[20]||=r(` (30 seconds by default) for the firing loop, one misfire handler period for misfire handling, and one check-in interval for cluster check-in; see the `,-1),c(m,{to:`/documentation/faq.html#system-clock-changes-ntp-corrections-manual-adjustments`},{default:i(()=>[...l[17]||=[r(`FAQ`,-1)]]),_:1}),l[21]||=r(`. To test clock movement, fake the clock instead of moving the machine's.`,-1)]),l[44]||=t(`<h3 id="clocks-in-a-cluster" tabindex="-1"><a class="header-anchor" href="#clocks-in-a-cluster"><span>Clocks in a cluster</span></a></h3><p>Cluster nodes compare a timestamp written by one node with the clock of another, so the clocks must agree.</p><ul><li>Each node writes its check-in time to the scheduler-state table.</li><li>A peer declares that node failed once <em>the peer&#39;s</em> clock passes that timestamp plus the node&#39;s check-in interval plus the check-in misfire threshold.</li><li>Both default to 7.5 seconds. A node is written off about fifteen seconds after its last check-in, and since it checks in every 7.5 seconds, only the other 7.5 seconds are slack.</li></ul><p><strong>A node whose clock runs more than about seven seconds ahead of a peer&#39;s can write off a healthy peer.</strong> The declaring node then runs cluster recovery against a node that is still working:</p><ul><li>it releases that node&#39;s acquired triggers so another node can take them;</li><li>it schedules recovery triggers for its recovery-requesting jobs;</li><li>it deletes its fired-trigger rows, so <code>[DisallowConcurrentExecution]</code> stops holding.</li></ul><p>The victim logs this line; alert on it:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">This scheduler instance (…) is still active but was recovered by another instance in the cluster.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>A clock is not the only way to miss a check-in.</strong> With a perfect clock, these miss check-ins too:</p><ul><li>a node pinned at 100% CPU, or a long garbage collection pause;</li><li>a paused virtual machine. Azure can pause virtual machines for up to 30 seconds during memory-preserving maintenance, twice the default detection window;</li><li>before 3.22 and 4.1, a refused database connection. One failed check-in backed off the full <code>DbRetryInterval</code> (15 seconds) and wrote its next row after the peers had stopped trusting it. Since then the check-in loop retries inside the window, so a blip shorter than the threshold no longer costs the node its row.</li></ul><p>Size the margin for the environment&#39;s worst <em>pause</em>, not its worst clock error.</p><p>What to do, in order:</p><ol><li><strong>Run time synchronisation on every node</strong>, and give the scheduler enough CPU headroom to check in on time. NTP is within a few milliseconds on a LAN; the failures in practice are unsynchronised or starved machines.</li><li><strong>If you cannot guarantee both, widen the window.</strong> Raise <code>quartz.jobStore.clusterCheckinMisfireThreshold</code>, or the check-in interval (<code>quartz.jobStore.clusterCheckinInterval</code>), past your environment&#39;s worst pause. The maintainer suggests a minute to people who hit this. A dead node&#39;s work then waits that much longer to be taken over.</li><li><strong>Keep the jobs idempotent anyway.</strong> The margin lowers the odds; it does not remove them.</li></ol><p>Clustering configuration is on <a href="/documentation/quartz-4.x/tutorial/advanced-enterprise-features">Advanced Enterprise Features (4.x)</a> and <a href="/documentation/quartz-3.x/tutorial/advanced-enterprise-features">(3.x)</a>.</p><h2 id="sizing-the-thread-pool-and-the-connection-pool" tabindex="-1"><a class="header-anchor" href="#sizing-the-thread-pool-and-the-connection-pool"><span>Sizing the thread pool and the connection pool</span></a></h2><h3 id="max-concurrency-is-a-permit-count-not-a-thread-count" tabindex="-1"><a class="header-anchor" href="#max-concurrency-is-a-permit-count-not-a-thread-count"><span>Max concurrency is a permit count, not a thread count</span></a></h3><p>The default thread pool is a semaphore of <code>MaxConcurrency</code> permits over the .NET thread pool, not a set of dedicated threads. Both versions default it to <strong>10</strong>.</p><table><thead><tr><th>Where</th><th>Spelling</th></tr></thead><tbody><tr><td>Flat key, both versions</td><td><code>quartz.threadPool.threadCount</code></td></tr><tr><td>Code</td><td><code>UseDefaultThreadPool(maxConcurrency)</code></td></tr><tr><td>4.x configuration</td><td><code>ThreadPool:MaxConcurrency</code></td></tr></tbody></table><ul><li><strong>A job that <code>await</code>s I/O</strong> holds its permit but releases the thread. Twenty jobs waiting on HTTP calls do not hold twenty threads.</li><li><strong>A job that blocks</strong> (<code>.Result</code>, <code>.Wait()</code>, <code>Thread.Sleep</code>) holds both. The .NET thread pool replaces a blocked thread at roughly one or two per second, so a burst of blocking work slows the whole application for minutes at almost no CPU. Do not block.</li><li><strong>A job that waits</strong> holds a permit, even with <code>await Task.Delay</code>. A job waiting an hour for a record to appear occupies a slot for an hour. Exit, and let a later firing do the work.</li></ul><p>Java Quartz&#39;s thread-count advice is about dedicated threads and does not apply to this pool. With a persistent store, size by database connections instead: <a href="#the-connection-pool-is-the-thread-pool-plus-three">see below</a>.</p><h3 id="the-connection-pool-is-the-thread-pool-plus-three" tabindex="-1"><a class="header-anchor" href="#the-connection-pool-is-the-thread-pool-plus-three"><span>The connection pool is the thread pool plus three</span></a></h3><p>Size the connection pool to at least <code>MaxConcurrency + 3</code>. The rule comes from Java Quartz and holds for Quartz.NET 4.x:</p><table><thead><tr><th>Consumer</th><th>Connections</th></tr></thead><tbody><tr><td>Executing jobs</td><td><code>MaxConcurrency</code></td></tr><tr><td>Scheduler thread, acquiring and firing triggers</td><td>1</td></tr><tr><td>Misfire handler, clustered or not</td><td>1</td></tr><tr><td>Cluster manager, when clustering is on</td><td>1</td></tr></tbody></table><p>A job holds no connection while it runs: the store is used on the scheduler thread before the job starts, and again when it finishes. But every worker can be in its completion write at the same instant, so <code>MaxConcurrency</code> is the burst ceiling. That makes <code>+ 3</code> clustered and <code>+ 2</code> otherwise. Taking the cluster-wide lock does not cost another connection; the row-lock handler uses the caller&#39;s.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">UseDefaultThreadPool</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrency</span><span class="token punctuation">:</span> <span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">UsePersistentStore</span><span class="token punctuation">(</span>s <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        s<span class="token punctuation">.</span><span class="token function">UseSystemTextJsonSerializer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        s<span class="token punctuation">.</span><span class="token function">UseClustering</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 20 workers, the scheduler thread, the misfire handler and the cluster manager</span></span>
<span class="line">        s<span class="token punctuation">.</span><span class="token function">UseSqlServer</span><span class="token punctuation">(</span><span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">connectionString</span><span class="token punctuation">}</span></span><span class="token string">;Max Pool Size=25&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Everything else in the process uses the same pool, and no Quartz setting bounds it:</strong></p><ul><li>the HTTP API and the dashboard take a connection per in-flight request;</li><li>a job that calls <code>IScheduler</code> takes a second one, alongside its own;</li><li>every scoped <code>DbContext</code> a job opens takes another.</li></ul><p>Size the pool for what the process does, not only for the scheduler.</p><p><strong>Do not answer a pool timeout by raising the pool.</strong> <code>Microsoft.Data.SqlClient</code> and Npgsql both default <code>Max Pool Size</code> to 100, and both fail after a fifteen-second wait with a message suggesting you raise it. A database works best with few active connections: HikariCP&#39;s <a href="https://github.com/brettwooldridge/HikariCP/wiki/About-Pool-Sizing" target="_blank" rel="noopener noreferrer">pool-sizing guide</a> recommends about <code>(core_count × 2) + effective_spindle_count</code>. That budget is shared by every node: ten schedulers with a pool of 25 each present 250 connections to one server.</p><p><strong>Use <code>MaxConcurrency</code> for admission control.</strong> Set it to the database&#39;s connection budget divided by the number of nodes, and the pool just above it. Queueing at the scheduler is visible, tunable and governed by your misfire instructions. Queueing inside ADO.NET is invisible and surfaces as a pool timeout that names the pool, not the cause.</p><h3 id="batching-changes-the-round-trips-not-the-connections" tabindex="-1"><a class="header-anchor" href="#batching-changes-the-round-trips-not-the-connections"><span>Batching changes the round trips, not the connections</span></a></h3><p><code>MaxBatchSize</code> (flat key <code>quartz.scheduler.batchTriggerAcquisitionMaxCount</code>) defaults to 1. Raising it acquires several triggers in one round trip. It adds no connections, but:</p><ul><li>A round that asks for more than one trigger takes the cluster-wide trigger-access lock; a single-trigger round does not.</li><li>Load across cluster nodes can become uneven: a node that acquires ten triggers holds them until it can run them.</li><li>Quartz 4.x refuses a <code>MaxBatchSize</code> larger than <code>MaxConcurrency</code> at startup, because triggers acquired beyond the available workers are held by that node until its pool drains.</li><li><code>BatchTriggerAcquisitionFireAheadTimeWindow</code> must be non-zero for a larger batch to have much effect; otherwise a batch holds only triggers that are already due.</li></ul><h3 id="scheduling-many-jobs-at-once" tabindex="-1"><a class="header-anchor" href="#scheduling-many-jobs-at-once"><span>Scheduling many jobs at once</span></a></h3><p><code>ScheduleJob</code> in a loop costs one lock acquisition and one transaction per job. <code>ScheduleJobs</code> takes a dictionary of jobs and their triggers and uses one of each:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">Dictionary<span class="token punctuation">&lt;</span>IJobDetail<span class="token punctuation">,</span> IReadOnlyCollection<span class="token punctuation">&lt;</span>ITrigger<span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> jobsDictionary <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">var</span></span> data <span class="token keyword">in</span> allData<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">var</span></span> triggerSet <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">HashSet<span class="token punctuation">&lt;</span>ITrigger<span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">IJobDetail</span> job <span class="token operator">=</span> JobBuilder<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Create</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>JobName<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span><span class="token string">&quot;jobData&quot;</span><span class="token punctuation">,</span> data<span class="token punctuation">.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    triggerSet<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>trigger<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    jobsDictionary<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>job<span class="token punctuation">,</span> triggerSet<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">ScheduleJobs</span><span class="token punctuation">(</span>jobsDictionary<span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ScheduleJobOptions</span> <span class="token punctuation">{</span> Replace <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>For reads, 4.x&#39;s paged, projected queries and the bulk <code>GetJobDetails(keys)</code> / <code>GetTriggers(keys)</code> fetch a page of keys in one round trip instead of one per key.</p><p>Before scaling this, ask whether you need a trigger per entity. A trigger per row scales to thousands, but a single trigger that scans for due rows is usually simpler to operate and needs no migration when the set of entities changes.</p><h2 id="operating-a-scheduler" tabindex="-1"><a class="header-anchor" href="#operating-a-scheduler"><span>Operating a scheduler</span></a></h2><h3 id="shutdown-has-a-deadline" tabindex="-1"><a class="header-anchor" href="#shutdown-has-a-deadline"><span>Shutdown has a deadline</span></a></h3><p><code>WaitForJobsToComplete</code> is off by default, so a shutdown returns while jobs are still running. From Quartz 4.1, such a shutdown still stops firing before it closes its thread pool, and gives the executions in flight a couple of seconds to report completion, so a job that was about to finish leaves nothing for a peer to recover.</p><p>With <code>WaitForJobsToComplete</code> on, the scheduler waits for the jobs, for as long as the host allows:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// The scheduler&#39;s wait for running jobs is bounded by the host&#39;s shutdown budget,</span></span>
<span class="line"><span class="token comment">// which is 30 seconds unless you say otherwise.</span></span>
<span class="line">services<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Configure</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>HostOptions<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>ShutdownTimeout <span class="token operator">=</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromMinutes</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">ConfigureScheduler</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span></span>
<span class="line">    options<span class="token punctuation">.</span>ShutdownJobInterruption <span class="token operator">=</span> ShutdownJobInterruption<span class="token punctuation">.</span>Always<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartzHostedService</span><span class="token punctuation">(</span>options <span class="token operator">=&gt;</span> options<span class="token punctuation">.</span>WaitForJobsToComplete <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The hosted service passes the host&#39;s shutdown token into the wait. <code>HostOptions.ShutdownTimeout</code> defaults to <strong>30 seconds</strong>.</p><ul><li><strong>4.x:</strong> the drain observes the token. When the budget runs out, the scheduler logs that it gave up waiting, then finishes tearing down the pool, the plugins and the job store.</li><li><strong>3.x:</strong> the pool&#39;s shutdown ignores the token and blocks until the jobs finish, so a long job makes the host&#39;s stop take as long as the job.</li></ul><p>Interrupting is a separate setting from waiting. Both versions default to <strong>not</strong> interrupting running jobs.</p><ul><li><strong>4.x:</strong> one setting, <code>ShutdownJobInterruption</code>.</li><li><strong>3.x:</strong> the flat keys <code>quartz.scheduler.interruptJobsOnShutdown</code> and <code>…interruptJobsOnShutdownWithWait</code>.</li></ul><p>Interrupting only signals the cancellation token. A job that does not check the token, or pass it to what it awaits, runs to completion regardless.</p><p>Plan for these:</p><ul><li><strong>The platform&#39;s budget must be larger than the application&#39;s.</strong> Kubernetes&#39; <code>terminationGracePeriodSeconds</code> also defaults to 30 seconds, so the two defaults collide. Whatever supervises the process (an orchestrator, a Windows service manager, an app-pool recycle) has its own budget; fit the application&#39;s inside it.</li><li><strong>Shutdown is terminal.</strong> A shut-down scheduler cannot restart; <code>Standby()</code> and <code>Start()</code> pause and resume. Do not call <code>Shutdown</code> yourself when a hosted service owns the scheduler; the host calls it.</li><li><strong>A longer timeout is rarely the fix.</strong> It slows every deployment and does not help when a node is evicted or a machine dies. What survives all of those is a job that can be interrupted and <a href="#assume-the-job-will-run-more-than-once">run again</a>.</li></ul><h3 id="one-name-per-cluster-one-id-per-node" tabindex="-1"><a class="header-anchor" href="#one-name-per-cluster-one-id-per-node"><span>One name per cluster, one id per node</span></a></h3><p>The most common cause of &quot;my job ran twice&quot; is two schedulers that were never one cluster. Check all five:</p><ul><li><strong>Every node of a cluster uses the same scheduler name.</strong> The name makes rows in the database belong to one logical scheduler. A name per node makes each node an independent scheduler that fires every trigger.</li><li><strong>Every node has a unique instance id.</strong> <code>AUTO</code> generates one. Never share an id between nodes.</li><li><strong>Clustering is on for every node.</strong> One node with it off breaks the cluster for all of them.</li><li><strong>The store is persistent.</strong> Two processes with in-memory stores are two schedulers with two copies of the schedule, and both fire it.</li><li><strong>No second, non-clustered scheduler uses the same tables.</strong> Results range from triggers that vanish without executing to deadlocks and corrupted state.</li></ul><p>Deployment topology counts as configuration. A staging slot, a canary or a second replica set that runs the same configuration against the same database is a cluster member; if its scheduler name matches, it takes work.</p>`,53),e(`p`,null,[l[23]||=e(`strong`,null,`Never write to Quartz's tables directly.`,-1),l[24]||=r(` The state machine spans several tables, and a hand-edited row causes the symptoms above. If a manual repair is the last resort, `,-1),c(m,{to:`/documentation/troubleshooting.html#triggers-stuck-in-acquired-state`},{default:i(()=>[...l[22]||=[r(`Troubleshooting`,-1)]]),_:1}),l[25]||=r(` has the statements and the warning that goes with them.`,-1)]),l[45]||=t(`<h3 id="what-the-trigger-states-mean" tabindex="-1"><a class="header-anchor" href="#what-the-trigger-states-mean"><span>What the trigger states mean</span></a></h3><p>As read from <code>QRTZ_TRIGGERS</code>:</p><table><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>WAITING</code></td><td>Normal. Acquirable when its next fire time arrives.</td></tr><tr><td><code>ACQUIRED</code></td><td>A node has reserved it to fire. Stuck here: that node stopped between reserving and firing.</td></tr><tr><td><code>BLOCKED</code></td><td>Another execution of the same <code>[DisallowConcurrentExecution]</code> job is running.</td></tr><tr><td><code>PAUSED</code> / <code>PAUSED_BLOCKED</code></td><td>Paused through the API or a group matcher.</td></tr><tr><td><code>ERROR</code></td><td>The job could not be <strong>built</strong>.</td></tr><tr><td><code>COMPLETE</code></td><td>Nothing left to fire.</td></tr></tbody></table><p>Two states are often misdiagnosed:</p><ul><li><strong>A trigger stuck in <code>BLOCKED</code></strong> almost always means a job that never returned: a synchronous call that hangs, a deadlock, an unawaited task.</li><li><strong><code>ERROR</code></strong> means the job&#39;s constructor threw, the container could not resolve it, or the store could not read the job detail. A job body that throws does <em>not</em> land here; that is an ordinary completed firing. Because it is a composition-root failure, an integration test that resolves the job usually reproduces it.</li></ul><p>Reset a trigger with <code>IScheduler.ResetTriggerFromErrorState(triggerKey)</code> on both versions; 4.x adds an overload taking a set of keys. See <a href="/documentation/quartz-4.x/how-tos/rescheduling-jobs#recovering-triggers-that-failed">Recovering triggers that failed</a>, which pages through them rather than assuming one query sees them all.</p><h3 id="listeners-run-in-the-middle-of-everything" tabindex="-1"><a class="header-anchor" href="#listeners-run-in-the-middle-of-everything"><span>Listeners run in the middle of everything</span></a></h3><p>A listener runs on the job&#39;s worker or on the scheduler thread, and its cost is added to every firing it matches. The history plugins are listeners too. Keep listeners short, and prefer listeners matched to specific jobs over global ones.</p><p>Catch exceptions inside a listener:</p><ul><li>A trigger or job listener that throws <em>before</em> the job runs stops the job running. The scheduler logs &quot;Job will NOT be executed!&quot;, tells the scheduler listeners, and completes the firing without executing anything.</li><li>One that throws afterwards stops the remaining listeners being notified.</li></ul><p>The firing is completed either way, so a throwing listener does not wedge a trigger, but it can silently cost you the execution.</p><h3 id="do-not-let-users-choose-the-job-type" tabindex="-1"><a class="header-anchor" href="#do-not-let-users-choose-the-job-type"><span>Do not let users choose the job type</span></a></h3><p>If an application lets users schedule jobs, the job type must not be one of their choices. <code>Quartz.Jobs</code> ships <code>NativeJob</code>, which runs an arbitrary operating-system command, and <code>SendMailJob</code>. A user who can name a job type and its data can run either, which amounts to command injection. Offer a fixed set of job types and validate their parameters.</p><p>The management surfaces need the same care:</p><ul><li><strong>3.x:</strong> the dashboard has a single authorization policy and a single read-only flag, with no per-scheduler policy. If different people should reach different schedulers, enforce that outside Quartz.NET.</li><li><strong>4.x:</strong> <code>QuartzDashboardOptions</code> and <code>QuartzHttpApiOptions</code> both take a <code>SchedulerAuthorizationPolicy</code>, evaluated per request against a <code>SchedulerResource</code> naming the scheduler. One <code>AuthorizationHandler&lt;TRequirement, SchedulerResource&gt;</code> holds each caller to its own scheduler. What a caller may <em>do</em> to that scheduler is still process-wide, through the dashboard&#39;s read-only flag.</li></ul>`,15),e(`p`,null,[l[28]||=r(`See `,-1),c(m,{to:`/documentation/quartz-4.x/multi-tenancy.html#authorizing-a-tenant-on-its-own-scheduler`},{default:i(()=>[...l[26]||=[r(`Authorizing a tenant on its own scheduler`,-1)]]),_:1}),l[29]||=r(` and `,-1),c(m,{to:`/documentation/tenancy-patterns.html#what-quartz-net-does-not-give-you`},{default:i(()=>[...l[27]||=[r(`Tenancy Patterns`,-1)]]),_:1}),l[30]||=r(`.`,-1)]),l[46]||=t(`<h2 id="what-to-watch" tabindex="-1"><a class="header-anchor" href="#what-to-watch"><span>What to watch</span></a></h2><p>The failures on this page (a starved pool, a node wrongly declared dead, a group stuck at its limit) show up as work that did <em>not</em> happen. A dashboard that only shows what ran cannot tell that from a quiet night.</p><p><strong>Traces</strong>, on both versions, come from an <code>ActivitySource</code> named <code>Quartz</code>:</p><table><thead><tr><th>Activity</th><th>Emitted for</th></tr></thead><tbody><tr><td><code>Quartz.Job.Execute</code></td><td>Each job execution; records a thrown exception</td></tr><tr><td><code>Quartz.Job.Veto</code></td><td>A vetoed firing</td></tr><tr><td><code>Quartz.JobStore.AcquireNextTriggers</code>, <code>.TriggersFired</code> and the rest</td><td>Each job store operation</td></tr></tbody></table><p>The job and trigger name and group, the job type and the fire instance id are attributes. Watch the store-operation spans: acquisition latency and its exceptions are where a struggling database first shows.</p><p><strong>Metrics are 4.x only</strong>; Quartz 3.x publishes none. There are eight instruments, on a meter named <code>Quartz</code>. <strong>Every measurement carries <code>quartz.scheduler.name</code> and <code>quartz.scheduler.id</code></strong>, so you can split by node and by scheduler with no instrumentation of your own.</p><table><thead><tr><th>Instrument</th><th>Shows</th></tr></thead><tbody><tr><td><code>quartz.job.execution.duration</code></td><td>Histogram in seconds, tagged <code>error.type</code> on failure; its count gives execution and failure counts</td></tr><tr><td><code>quartz.job.execution.active</code></td><td>Executions in flight; stuck at a ceiling means a starved pool or a saturated group</td></tr><tr><td><code>quartz.trigger.misfire</code></td><td>Firings that did not happen on time; alert on it for a slipping schedule or a group stuck at its limit</td></tr><tr><td><code>quartz.trigger.acquisition.duration</code></td><td>How long the scheduling loop waited on the store; a struggling database shows here first</td></tr><tr><td><code>quartz.trigger.acquired</code></td><td>Triggers acquired</td></tr><tr><td><code>quartz.cluster.checkin.duration</code></td><td>Cluster check-in time</td></tr><tr><td><code>quartz.cluster.recovery.trigger</code></td><td>A node&#39;s work being taken over</td></tr><tr><td><code>quartz.jobstore.operation.duration</code></td><td>Store operations, tagged with the operation&#39;s name</td></tr></tbody></table>`,7),e(`p`,null,[l[32]||=r(`The `,-1),c(m,{to:`/documentation/quartz-4.x/packages/opentelemetry-integration.html#metrics`},{default:i(()=>[...l[31]||=[r(`OpenTelemetry page`,-1)]]),_:1}),l[33]||=r(` lists each instrument's attributes.`,-1)]),l[47]||=t(`<p><strong>There is no trigger-state gauge.</strong> Query the store instead: count <code>QRTZ_TRIGGERS</code> by <code>TRIGGER_STATE</code>, and alert on <code>ERROR</code> and on <code>BLOCKED</code> rows older than your longest job. Count <code>QRTZ_FIRED_TRIGGERS</code> to see what the cluster believes is running; in 4.x, <code>IScheduler.QueryFireInstances</code> answers that without SQL.</p><p><strong>The health check</strong> asserts only that the scheduler is in a state that can fire and that the job store answers a query. It does <strong>not</strong> assert that any trigger is firing, so pair it with an alert on a job you expect to see regularly.</p><ul><li><strong>4.x:</strong> in the core package, with no web stack required. Register it explicitly: <code>services.AddHealthChecks().AddQuartz()</code>, or <code>q.AddQuartzHealthChecks()</code> inside a named scheduler&#39;s <code>AddQuartz(name, …)</code> callback. A standby scheduler reports <em>degraded</em>.</li><li><strong>3.x:</strong> in <code>Quartz.AspNetCore</code>, registered by <code>AddQuartzServer()</code>. It reports healthy or unhealthy from <code>IsStarted</code> alone, so a scheduler in standby passes.</li></ul><p><strong>Logging is the first diagnostic step.</strong> Misfire handling and every cluster-recovery decision log at information level when they act; trigger acquisition logs at debug. That makes &quot;no triggers were acquired&quot; and &quot;someone recovered this node&quot; readable after the fact. Most investigations in this project&#39;s issue tracker end once logging is on. Configure it before you need it.</p><p>Setup is on <a href="/documentation/quartz-4.x/packages/opentelemetry-integration">Observability (4.x)</a> and <a href="/documentation/quartz-3.x/packages/opentelemetry-integration">OpenTelemetry Integration (3.x)</a>.</p><h2 id="see-also" tabindex="-1"><a class="header-anchor" href="#see-also"><span>See also</span></a></h2>`,6),e(`ul`,null,[e(`li`,null,[c(m,{to:`/documentation/troubleshooting.html`},{default:i(()=>[...l[34]||=[r(`Troubleshooting`,-1)]]),_:1}),l[35]||=r(`: symptoms, and what to do about each`,-1)]),e(`li`,null,[c(m,{to:`/documentation/faq.html`},{default:i(()=>[...l[36]||=[r(`FAQ`,-1)]]),_:1}),l[37]||=r(`: daylight saving and clock changes in more detail`,-1)]),e(`li`,null,[c(m,{to:`/documentation/tenancy-patterns.html`},{default:i(()=>[...l[38]||=[r(`Tenancy Patterns`,-1)]]),_:1}),l[39]||=r(`: partitioning a scheduler between tenants`,-1)]),l[40]||=e(`li`,null,[e(`a`,{href:`/documentation/quartz-4.x/configuration/reference`},`Configuration Reference (4.x)`),r(` and `),e(`a`,{href:`/documentation/quartz-3.x/configuration/reference`},`(3.x)`),r(`: every setting named here, with its default`)],-1)])])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};